from typing import Any

import aiosqlite
from fastapi import APIRouter, HTTPException
from pydantic import BaseModel, field_validator

from .config import SearchRecConfig


class ItemIn(BaseModel):
    item_id:   str
    name:      str
    category:  str   = ""
    price:     float = 0.0
    image_url: str   = ""
    in_stock:  bool  = True

    @field_validator("item_id", "name")
    @classmethod
    def must_be_non_empty(cls, v: str) -> str:
        if not v.strip():
            raise ValueError("must not be empty")
        return v.strip()


class ItemBatch(BaseModel):
    items: list[ItemIn]

    @field_validator("items")
    @classmethod
    def at_least_one(cls, v: list[ItemIn]) -> list[ItemIn]:
        if not v:
            raise ValueError("items list must not be empty")
        return v


def items_router(config: SearchRecConfig) -> APIRouter:
    router = APIRouter(tags=["items"])

    @router.put("/api/items")
    @router.post("/api/items")
    async def upsert_items(batch: ItemBatch):
        rows = [
            (i.item_id, i.name, i.category, i.price, i.image_url, int(i.in_stock))
            for i in batch.items
        ]
        async with aiosqlite.connect(config.db_path) as db:
            await db.executemany(
                "INSERT OR REPLACE INTO items (item_id, name, category, price, image_url, in_stock) VALUES (?,?,?,?,?,?)",
                rows,
            )
            await db.commit()
        return {"synced": len(rows)}

    @router.delete("/api/items/{item_id}")
    async def delete_item(item_id: str):
        async with aiosqlite.connect(config.db_path) as db:
            await db.execute("DELETE FROM items WHERE item_id = ?", (item_id,))
            await db.commit()
        return {"deleted": item_id}

    @router.get("/api/items/search")
    async def search_items(q: str = "", limit: int = 50):
        if limit < 1 or limit > 100:
            raise HTTPException(status_code=400, detail="limit must be between 1 and 100")
        async with aiosqlite.connect(config.db_path) as db:
            db.row_factory = aiosqlite.Row
            if q.strip():
                cursor = await db.execute(
                    """
                    SELECT item_id, name, category, price, image_url, in_stock
                    FROM items WHERE name LIKE ? OR category LIKE ?
                    ORDER BY name LIMIT ?
                    """,
                    (f"%{q}%", f"%{q}%", limit),
                )
            else:
                cursor = await db.execute(
                    """
                    SELECT item_id, name, category, price, image_url, in_stock
                    FROM items ORDER BY category, name LIMIT ?
                    """,
                    (limit,),
                )
            rows = await cursor.fetchall()
        return {"items": [dict(r) for r in rows]}

    @router.get("/api/items/{item_id}")
    async def get_item(item_id: str):
        async with aiosqlite.connect(config.db_path) as db:
            db.row_factory = aiosqlite.Row
            cursor = await db.execute(
                "SELECT item_id, name, category, price, image_url, in_stock FROM items WHERE item_id = ?",
                (item_id,),
            )
            row = await cursor.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail=f"Item '{item_id}' not found")
        return dict(row)

    return router


class SearchRec:
    def __init__(self, db_path: str = "./rec.db"):
        self._db_path = db_path

    async def sync_products(
        self,
        products: list[dict[str, Any]],
        *,
        upsert: bool = True,
    ) -> dict:
        rows = [
            (
                p["item_id"],
                p["name"],
                p.get("category", ""),
                float(p.get("price", 0.0)),
                p.get("image_url", ""),
                int(p.get("in_stock", True)),
            )
            for p in products
        ]
        stmt = (
            "INSERT OR REPLACE INTO items (item_id, name, category, price, image_url, in_stock) VALUES (?,?,?,?,?,?)"
            if upsert else
            "INSERT OR IGNORE  INTO items (item_id, name, category, price, image_url, in_stock) VALUES (?,?,?,?,?,?)"
        )
        async with aiosqlite.connect(self._db_path) as db:
            await db.executemany(stmt, rows)
            await db.commit()
        return {"synced": len(rows)}
